 static void move(Object n,double x,double y,double z,double speed){c(c(n,"getNavigation"),"moveTo",x,y,z,speed);}static void move(Object n,Object p,double speed){move(n,num(c(p,"getX")),num(c(p,"getY")),num(c(p,"getZ")),speed);}
